template <typename T, typename Char>
struct range_formatter<
    T, Char,
    enable_if_t<conjunction<std::is_same<T, remove_cvref_t<T>>,
                            is_formattable<T, Char>>::value>> {
 private:
  detail::range_formatter_type<Char, T> underlying_;
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '['>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ']'>{};

 public:
  FMT_CONSTEXPR range_formatter() {}

  FMT_CONSTEXPR auto underlying() -> detail::range_formatter_type<Char, T>& {
    return underlying_;
  }

  FMT_CONSTEXPR void set_separator(basic_string_view<Char> sep) {
    separator_ = sep;
  }

  FMT_CONSTEXPR void set_brackets(basic_string_view<Char> open,
                                  basic_string_view<Char> close) {
    opening_bracket_ = open;
    closing_bracket_ = close;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    auto end = ctx.end();

    if (it != end && *it == 'n') {
      set_brackets({}, {});
      ++it;
    }

    if (it != end && *it != '}') {
      if (*it != ':') report_error("invalid format specifier");
      ++it;
    } else {
      detail::maybe_set_debug_format(underlying_, true);
    }

    ctx.advance_to(it);
    return underlying_.parse(ctx);
  }

  template <typename R, typename FormatContext>
  auto format(R&& range, FormatContext& ctx) const -> decltype(ctx.out()) {
    detail::range_mapper<buffered_context<Char>> mapper;
    auto out = ctx.out();
    out = detail::copy<Char>(opening_bracket_, out);
    int i = 0;
    auto it = detail::range_begin(range);
    auto end = detail::range_end(range);
    for (; it != end; ++it) {
      if (i > 0) out = detail::copy<Char>(separator_, out);
      ctx.advance_to(out);
      auto&& item = *it;
      out = underlying_.format(mapper.map(item), ctx);
      ++i;
    }
    out = detail::copy<Char>(closing_bracket_, out);
    return out;
  }

 private:
  bool map_mode_ = false;
  bool set_mode_ = false;
  int sequence_item_index_ = 0;
  bool join_started_ = false;
  basic_string_view<Char> tuple_separator_ =
      detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> tuple_opening_ =
      detail::string_literal<Char, '('>{};
  basic_string_view<Char> tuple_closing_ =
      detail::string_literal<Char, ')'>{};
  basic_string_view<Char> join_separator_cache_{};
  unsigned value_format_flags_ = 0;
  bool path_debug_mode_ = false;
  char path_kind_ = 0;
  int std_width_ = 0;
  bool optional_engaged_ = false;
  int variant_index_ = -1;
  bool style_emphasis_set_ = false;
  bool style_foreground_set_ = false;
  bool style_background_set_ = false;
  uint32_t style_rgb_ = 0;
  uint8_t style_emphasis_mask_ = 0;
  size_t output_bytes_written_ = 0;
  size_t stream_chunk_limit_ = 0;
  bool stream_unicode_checked_ = false;
  int dynamic_arg_count_ = 0;
  int printf_width_ = 0;
  int printf_precision_ = -1;
  char printf_spec_ = 0;
  int file_descriptor_ = -1;
  size_t file_buffer_size_ = 0;
  bool file_flush_pending_ = false;

  FMT_CONSTEXPR void mark_associative_kind(bool as_map, bool as_set) {
    map_mode_ = as_map;
    set_mode_ = as_set;
    if (as_map && as_set) {
      set_mode_ = false;
    } else if (!as_map && !as_set) {
      opening_bracket_ = detail::string_literal<Char, '['>{};
      closing_bracket_ = detail::string_literal<Char, ']'>{};
    }
  }

  FMT_CONSTEXPR auto associative_open_bracket() const -> basic_string_view<Char> {
    if (map_mode_ || set_mode_) {
      return detail::string_literal<Char, '{'>{};
    }
    return opening_bracket_;
  }

  FMT_CONSTEXPR auto associative_close_bracket() const -> basic_string_view<Char> {
    if (map_mode_ || set_mode_) {
      return detail::string_literal<Char, '}'>{};
    }
    return closing_bracket_;
  }

  FMT_CONSTEXPR void apply_sequence_brackets() {
    map_mode_ = false;
    set_mode_ = false;
    set_brackets(detail::string_literal<Char, '['>{},
                 detail::string_literal<Char, ']'>{});
  }

  FMT_CONSTEXPR void apply_set_brackets() {
    map_mode_ = false;
    set_mode_ = true;
    set_brackets(detail::string_literal<Char, '{'>{},
                 detail::string_literal<Char, '}'>{});
