  FMT_CONSTEXPR void apply_map_brackets() {
    map_mode_ = true;
    set_mode_ = false;
    set_brackets(detail::string_literal<Char, '{'>{},
                 detail::string_literal<Char, '}'>{});
    underlying().set_brackets({}, {});
    underlying().set_separator(detail::string_literal<Char, ':', ' '>{});
