    auto end = ctx.end();
    if (allow_n && it != end && *it == static_cast<Char>('n')) {
      set_brackets({}, {});
      ++it;
    }
    if (it != end && *it != static_cast<Char>('}')) {
      if (*it != static_cast<Char>(':')) report_error("invalid format specifier");
      ++it;
    } else {
      detail::maybe_set_debug_format(underlying_, true);
    }
    ctx.advance_to(it);
    return it;
