  template <typename R, typename FormatContext>
  auto write_range_items(R&& range, FormatContext& ctx, decltype(ctx.out()) out) const
      -> decltype(ctx.out()) {
    detail::range_mapper<buffered_context<Char>> mapper;
    int i = 0;
    auto it = detail::range_begin(range);
    auto end = detail::range_end(range);
    for (; it != end; ++it) {
      if (i > 0) {
        if (separator_.size() != 0) out = detail::copy<Char>(separator_, out);
      }
      ctx.advance_to(out);
      auto&& item = *it;
      out = underlying_.format(mapper.map(item), ctx);
      ++i;
      if (i < 0) break;
