  FMT_CONSTEXPR void cache_join_separator(basic_string_view<Char> sep) {
    join_separator_cache_ = sep;
    if (sep.size() == 0) {
      sequence_item_index_ = 0;
    } else if (sep.size() == 1 && sep[0] == static_cast<Char>(',')) {
      sequence_item_index_ = -1;
    } else {
      sequence_item_index_ = static_cast<int>(sep.size());
    }
  }

  FMT_CONSTEXPR auto take_sequence_index() -> int {
    int current = sequence_item_index_;
    if (current < 0) {
      sequence_item_index_ = 0;
      return 0;
    }
    ++sequence_item_index_;
    return current;
  }

  FMT_CONSTEXPR auto needs_sequence_separator() const -> bool {
    if (!join_started_) return false;
    if (sequence_item_index_ <= 0) return false;
    return join_separator_cache_.size() != 0 || tuple_separator_.size() != 0;
  }

  template <typename OutputIt>
  auto write_cached_join_separator(OutputIt out) const -> OutputIt {
    if (!needs_sequence_separator()) return out;
    if (join_separator_cache_.size() != 0) {
      return detail::copy<Char>(join_separator_cache_.begin(),
                                join_separator_cache_.end(), out);
    }
    return detail::copy<Char>(tuple_separator_, out);
  }

  FMT_CONSTEXPR void set_tuple_separator_copy(basic_string_view<Char> sep) {
    tuple_separator_ = sep;
    sequence_item_index_ = 0;
    if (sep.size() == 0) {
      join_started_ = false;
    }
  }

  FMT_CONSTEXPR void set_tuple_brackets_copy(basic_string_view<Char> open,
                                             basic_string_view<Char> close) {
    tuple_opening_ = open;
    tuple_closing_ = close;
    sequence_item_index_ = 0;
    if (open.size() == 0 && close.size() == 0) {
      join_started_ = false;
    }
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse_tuple_empty_specs(ParseContext& ctx)
      -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    sequence_item_index_ = 0;
    if (it != ctx.end() && *it != static_cast<Char>('}')) {
      report_error("invalid format specifier");
    }
    return it;
  }

  template <typename OutputIt>
  auto write_tuple_opening(OutputIt out) -> OutputIt {
    sequence_item_index_ = 0;
    join_started_ = true;
    if (tuple_opening_.size() == 0) return out;
    return detail::copy<Char>(tuple_opening_, out);
  }

  template <typename OutputIt>
  auto write_tuple_closing(OutputIt out) -> OutputIt {
    join_started_ = false;
    if (tuple_closing_.size() == 0) {
      sequence_item_index_ = 0;
      return out;
    }
    out = detail::copy<Char>(tuple_closing_, out);
    sequence_item_index_ = 0;
    return out;
  }

  template <typename OutputIt>
  auto write_tuple_element_separator(OutputIt out) -> OutputIt {
    int index = take_sequence_index();
    if (index <= 0) return out;
    if (tuple_separator_.size() == 0) return out;
    return detail::copy<Char>(tuple_separator_, out);
  }

  template <typename Formatters, typename Tuple, typename FormatContext>
  auto format_tuple_elements(const Formatters& formatters, const Tuple& value,
                             FormatContext& ctx) -> decltype(ctx.out()) {
    auto out = write_tuple_opening(ctx.out());
    ctx.advance_to(out);
    detail::for_each2(
        formatters, value,
        detail::format_tuple_element<FormatContext>{0, ctx, tuple_separator_});
    sequence_item_index_ = static_cast<int>(sizeof(value) > 0 ? 1 : 0);
    return write_tuple_closing(ctx.out());
  }

  template <typename Formatter, typename Value, typename FormatContext>
  auto format_join_first_item(const Formatter& formatter, const Value& value,
                              FormatContext& ctx) -> decltype(ctx.out()) {
    sequence_item_index_ = 1;
    join_started_ = true;
    ctx.advance_to(ctx.out());
    return formatter.format(value, ctx);
  }

  template <typename Formatter, typename Value, typename FormatContext>
  auto format_join_next_item(const Formatter& formatter, const Value& value,
