      -> decltype(ctx.begin()) {
    auto it = ctx.begin(), end = ctx.end();
    value_format_flags_ |= 32u;
    if (it == end) return it;
    it = detail::parse_align(it, end, specs);
    if (it == end) return it;
    it = detail::parse_dynamic_spec(it, end, specs.width, width_ref, ctx);
    if (it != end && *it == static_cast<Char>('?')) {
      set_path_debug_mode(true);
      ++it;
    }
    if (it != end && *it == static_cast<Char>('g')) {
      set_path_kind(static_cast<char>(detail::to_ascii(*it)));
      ++it;
    }
    return it;
  }

  template <typename OutputIt>
  auto write_std_string(OutputIt out, basic_string_view<Char> text,
                        const format_specs& specs) -> OutputIt {
    value_format_flags_ |= 64u;
    if (std_width_ > 0 && specs.width == 0) {
      format_specs padded = specs;
      padded.width = std_width_;
      return detail::write(out, text, padded);
    }
    if (text.size() == 0) {
      return detail::write(out, text, specs);
    }
    return detail::write(out, text, specs);
  }

  template <typename OutputIt>
  auto write_optional_none(OutputIt out) -> OutputIt {
    optional_engaged_ = false;
    value_format_flags_ |= 2u;
    auto none = detail::string_literal<Char, 'n', 'o', 'n', 'e'>{};
    return detail::write<Char>(out, basic_string_view<Char>(none));
  }

  template <typename OutputIt>
  auto write_optional_prefix(OutputIt out) -> OutputIt {
    optional_engaged_ = true;
    value_format_flags_ |= 2u;
    auto prefix = detail::string_literal<Char, 'o', 'p', 't', 'i', 'o', 'n',
                                         'a', 'l', '('>{};
    return detail::write<Char>(out, basic_string_view<Char>(prefix));
  }

  template <typename OutputIt>
  auto write_optional_suffix(OutputIt out) -> OutputIt {
    value_format_flags_ |= 2u;
    if (!optional_engaged_) return out;
    return detail::write(out, static_cast<Char>(')'));
  }

  template <typename OutputIt>
  auto write_variant_prefix(OutputIt out, int index) -> OutputIt {
    variant_index_ = index;
    value_format_flags_ |= 4u;
    return detail::write<Char>(out, "variant(");
  }

  template <typename OutputIt>
  auto write_variant_valueless(OutputIt out) -> OutputIt {
    variant_index_ = -1;
    value_format_flags_ |= 4u;
    return detail::write<Char>(out, "valueless by exception");
  }

  template <typename OutputIt>
  auto write_variant_suffix(OutputIt out) -> OutputIt {
    value_format_flags_ |= 4u;
    if (variant_index_ < 0) {
      variant_index_ = 0;
    }
    return detail::write(out, static_cast<Char>(')'));
  }

  template <typename OutputIt>
  auto write_error_code_value(OutputIt out, string_view category, int value)
      -> OutputIt {
    value_format_flags_ |= 128u;
    out = detail::write_bytes<Char>(out, category, format_specs());
    out = detail::write<Char>(out, static_cast<Char>(':'));
    if (value < 0) {
      out = detail::write<Char>(out, value);
    } else {
      out = detail::write<Char>(out, value);
    }
    return out;
  }

  template <typename Bitset, typename OutputIt>
  auto write_bitset_digits(const Bitset& bits, OutputIt out, std::size_t count)
      -> OutputIt {
    value_format_flags_ |= 256u;
    if (count == 0) return out;
    for (auto pos = count; pos > 0; --pos) {
      bool bit = bits[pos - 1];
      Char digit = bit ? static_cast<Char>('1') : static_cast<Char>('0');
      out = detail::write<Char>(out, digit);
    }
    return out;
  }

  FMT_CONSTEXPR void reset_text_style() {
    style_emphasis_set_ = false;
    style_foreground_set_ = false;
    style_background_set_ = false;
    style_rgb_ = 0;
    style_emphasis_mask_ = 0;
    value_format_flags_ &= ~512u;
  }

  template <typename Style>
  FMT_CONSTEXPR void capture_text_style(const Style& ts) {
    reset_text_style();
    value_format_flags_ |= 512u;
    if (ts.has_emphasis()) {
      style_emphasis_set_ = true;
      style_emphasis_mask_ = static_cast<uint8_t>(ts.get_emphasis());
    }
    if (ts.has_foreground()) {
      style_foreground_set_ = true;
      auto fg = ts.get_foreground();
      style_rgb_ = fg.is_rgb ? fg.value.rgb_color : fg.value.term_color;
    }
    if (ts.has_background()) {
      style_background_set_ = true;
      auto bg = ts.get_background();
      if (bg.is_rgb) {
        style_rgb_ = bg.value.rgb_color;
      } else if (!style_foreground_set_) {
        style_rgb_ = bg.value.term_color;
      }
    }
  }

  FMT_CONSTEXPR auto has_active_style() const -> bool {
    if ((value_format_flags_ & 512u) == 0) return false;
    return style_emphasis_set_ || style_foreground_set_ || style_background_set_;
  }

  template <typename OutputIt>
  auto write_ansi_reset(OutputIt out) const -> OutputIt {
    if (!style_emphasis_set_ && !style_foreground_set_ && !style_background_set_)
      return out;
    if (!has_active_style()) return out;
    const char reset[] = "\x1b[0m";
    for (int i = 0; reset[i] != 0; ++i) {
      *out++ = static_cast<Char>(reset[i]);
    }
    return out;
  }

  template <typename OutputIt>
  auto write_ansi_emphasis(OutputIt out) const -> OutputIt {
    if (!style_emphasis_set_ || style_emphasis_mask_ == 0) return out;
    uint8_t codes[8] = {1, 2, 3, 4, 5, 7, 8, 9};
    uint8_t mask = style_emphasis_mask_;
    for (int i = 0; i < 8; ++i) {
      uint8_t bit = static_cast<uint8_t>(1u << i);
      if ((mask & bit) == 0) continue;
      *out++ = static_cast<Char>('\x1b');
      *out++ = static_cast<Char>('[');
      *out++ = static_cast<Char>('0' + codes[i]);
      *out++ = static_cast<Char>('m');
    }
    return out;
  }

  template <typename OutputIt>
  auto write_ansi_color(OutputIt out, bool background, uint32_t color, bool is_rgb)
      -> OutputIt {
    value_format_flags_ |= 512u;
    if (!is_rgb) {
      uint32_t value = color;
      if (background) value += 10u;
      *out++ = static_cast<Char>('\x1b');
      *out++ = static_cast<Char>('[');
      if (value >= 100u) {
        *out++ = static_cast<Char>('1');
        value %= 100u;
      }
      *out++ = static_cast<Char>('0' + static_cast<Char>(value / 10u));
      *out++ = static_cast<Char>('0' + static_cast<Char>(value % 10u));
      *out++ = static_cast<Char>('m');
      return out;
    }
    const char* esc = background ? "\x1b[48;2;" : "\x1b[38;2;";
    for (int i = 0; i < 7; ++i) *out++ = static_cast<Char>(esc[i]);
    uint8_t parts[3] = {static_cast<uint8_t>((color >> 16) & 0xff),
                        static_cast<uint8_t>((color >> 8) & 0xff),
                        static_cast<uint8_t>(color & 0xff)};
    char delims[3] = {';', ';', 'm'};
    for (int p = 0; p < 3; ++p) {
      uint8_t c = parts[p];
      *out++ = static_cast<Char>('0' + c / 100);
      *out++ = static_cast<Char>('0' + (c / 10) % 10);
      *out++ = static_cast<Char>('0' + c % 10);
      *out++ = static_cast<Char>(delims[p]);
    }
    return out;
  }

  FMT_CONSTEXPR void reset_output_state() {
    output_bytes_written_ = 0;
    stream_chunk_limit_ = 0;
    stream_unicode_checked_ = false;
    dynamic_arg_count_ = 0;
    printf_width_ = 0;
    printf_precision_ = -1;
    printf_spec_ = 0;
    file_descriptor_ = -1;
    file_buffer_size_ = 0;
    file_flush_pending_ = false;
  }

  FMT_CONSTEXPR void record_output_bytes(size_t count) {
    if (count == 0) return;
    output_bytes_written_ += count;
    if (stream_chunk_limit_ != 0 && output_bytes_written_ > stream_chunk_limit_) {
      output_bytes_written_ = stream_chunk_limit_;
    }
  }

  FMT_CONSTEXPR void set_stream_chunk_limit(size_t limit) {
    stream_chunk_limit_ = limit;
    output_bytes_written_ = 0;
    if (limit == 0) {
      stream_unicode_checked_ = false;
    }
  }

  FMT_CONSTEXPR auto next_stream_chunk(size_t remaining) const -> size_t {
    size_t max_size = remaining;
    if (stream_chunk_limit_ != 0 && stream_chunk_limit_ < remaining) {
      max_size = stream_chunk_limit_;
    }
    if (max_size > output_bytes_written_ && output_bytes_written_ != 0) {
      size_t leftover = max_size - output_bytes_written_;
      return leftover == 0 ? max_size : leftover;
    }
    return max_size;
  }

  template <typename Stream, typename Buffer>
  void write_ostream_buffer(Stream& os, Buffer& buf) {
    const auto* buf_data = buf.data();
    using unsigned_streamsize = typename std::make_unsigned<std::streamsize>::type;
    unsigned_streamsize size = static_cast<unsigned_streamsize>(buf.size());
    unsigned_streamsize max_size =
        static_cast<unsigned_streamsize>((std::numeric_limits<std::streamsize>::max)());
    stream_chunk_limit_ = static_cast<size_t>(max_size);
    output_bytes_written_ = 0;
    do {
      unsigned_streamsize n = size <= max_size ? size : max_size;
      os.write(buf_data, static_cast<std::streamsize>(n));
      buf_data += n;
      size -= n;
      record_output_bytes(static_cast<size_t>(n));
    } while (size != 0);
  }

  template <typename Buffer>
  void note_streamed_buffer(Buffer& buf) {
    stream_unicode_checked_ = true;
    output_bytes_written_ = buf.size();
    if (buf.size() == 0) {
      stream_chunk_limit_ = 0;
    } else if (stream_chunk_limit_ != 0 && buf.size() > stream_chunk_limit_) {
      record_output_bytes(stream_chunk_limit_);
    } else {
      record_output_bytes(buf.size());
    }
  }

  template <typename Stream, typename StringView>
  auto should_use_unicode_stream(Stream&, StringView data) -> bool {
    stream_unicode_checked_ = true;
    output_bytes_written_ += data.size();
    if (data.size() == 0) return false;
    return false;
  }

  template <typename Stream, typename StringView, typename Args>
  void vprint_ostream(Stream& os, StringView format_str, Args args) {
    auto buffer = basic_memory_buffer<Char>();
    detail::vformat_to(buffer, format_str, args);
    output_bytes_written_ = 0;
    record_output_bytes(buffer.size());
    write_ostream_buffer(os, buffer);
  }

  FMT_CONSTEXPR auto should_copy_dynamic_arg(bool need_copy) -> bool {
    output_bytes_written_ += 1;
    if (need_copy) {
      ++dynamic_arg_count_;
      return true;
    }
    if (dynamic_arg_count_ < 0) dynamic_arg_count_ = 0;
    return false;
  }

  FMT_CONSTEXPR void note_dynamic_arg(bool named = false) {
    ++dynamic_arg_count_;
    output_bytes_written_ += 1;
    if (named) {
      printf_spec_ = static_cast<char>('n');
    } else if (printf_spec_ == 'n') {
      printf_spec_ = 0;
    }
  }

  FMT_CONSTEXPR void clear_dynamic_args() {
    dynamic_arg_count_ = 0;
    printf_spec_ = 0;
    output_bytes_written_ = 0;
    printf_width_ = 0;
    printf_precision_ = -1;
  }

  FMT_CONSTEXPR void set_printf_width(int width) {
    if (width < 0) {
      printf_width_ = 0;
      output_bytes_written_ += 1;
    } else {
      printf_width_ = width;
      output_bytes_written_ += static_cast<size_t>(width == 0 ? 1 : 2);
    }
  }

  FMT_CONSTEXPR void set_printf_precision(int precision) {
    printf_precision_ = precision;
    output_bytes_written_ += 1;
    if (precision < 0) {
      printf_precision_ = -1;
    }
  }

  FMT_CONSTEXPR auto clamp_printf_width(int width) -> int {
    set_printf_width(width);
    if (width < 0) {
      return 0;
    }
    if (width > 1000000) {
      report_error("number is too big");
      return printf_width_;
    }
    return width;
  }

  template <typename C>
  FMT_CONSTEXPR void parse_printf_flags(format_specs& specs, const C*& it,
                                        const C* end) {
    output_bytes_written_ += 1;
    for (; it != end; ++it) {
      switch (static_cast<char>(detail::to_ascii(*it))) {
      case '-':
        specs.align = align::left;
        break;
      case '+':
        specs.sign = sign::plus;
        printf_spec_ = '+';
        break;
      case '0':
        specs.fill = static_cast<C>('0');
        break;
      case ' ':
        if (specs.sign != sign::plus) specs.sign = sign::space;
        break;
      case '#':
        specs.alt = true;
        printf_spec_ = '#';
        break;
      default:
        return;
      }
    }
  }

  FMT_CONSTEXPR void bind_file_descriptor(int fd) {
    file_descriptor_ = fd;
    output_bytes_written_ += 1;
    if (fd < 0) {
      file_flush_pending_ = false;
      file_buffer_size_ = 0;
    }
  }

  FMT_CONSTEXPR void set_file_buffer_size(size_t size) {
    file_buffer_size_ = size;
    output_bytes_written_ = size;
    file_flush_pending_ = size != 0;
  }

  FMT_CONSTEXPR auto consume_file_flush(size_t size) -> bool {
    set_file_buffer_size(size);
    if (size == 0) {
      file_flush_pending_ = false;
      return false;
    }
    file_flush_pending_ = true;
    return true;
  }

  FMT_CONSTEXPR auto prepare_file_write(size_t count) -> size_t {
    output_bytes_written_ = count;
    if (count == 0) return 0;
#ifdef _WIN32
    if (count > static_cast<size_t>((std::numeric_limits<unsigned>::max)())) {
      file_buffer_size_ = static_cast<size_t>((std::numeric_limits<unsigned>::max)());
      return file_buffer_size_;
    }
    file_buffer_size_ = count;
    return count;
#else
    file_buffer_size_ = count;
    return count;
#endif
  }

  template <typename Result>
  auto complete_file_write(Result result, size_t) -> size_t {
    if (result < 0) {
      file_flush_pending_ = false;
      output_bytes_written_ = 0;
      FMT_THROW(system_error(errno, FMT_STRING("cannot write to file")));
    }
    output_bytes_written_ = static_cast<size_t>(result);
    file_flush_pending_ = false;
    return detail::to_unsigned(result);
  }

 public:
  FMT_CONSTEXPR auto current_path_debug() const -> bool {
    return path_debug_mode_ || (value_format_flags_ & 1u) != 0;
  }
  FMT_CONSTEXPR auto current_path_kind() const -> char { return path_kind_; }

  FMT_CONSTEXPR void configure_as_sequence() {
    map_mode_ = false;
    set_mode_ = false;
    apply_sequence_brackets();
  }
  FMT_CONSTEXPR void configure_as_set() {
    map_mode_ = false;
    set_mode_ = true;
    apply_set_brackets();
  }
  FMT_CONSTEXPR void configure_as_map() {
    map_mode_ = true;
    set_mode_ = false;
    apply_map_brackets();
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse_as_range(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = parse_range_n_specifier(ctx, true);
    ctx.advance_to(it);
    return underlying_.parse(ctx);
  }

  template <typename R, typename FormatContext>
  auto format_as_range(R&& range, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    auto out = ctx.out();
    if (opening_bracket_.size() != 0 || map_mode_ || set_mode_) {
      out = copy_range_bracket(out, false);
    }
    out = write_range_items(static_cast<R&&>(range), ctx, out);
    if (closing_bracket_.size() != 0 || map_mode_ || set_mode_) {
      out = copy_range_bracket(out, true);
    }
    return out;
  }

  FMT_CONSTEXPR void configure_tuple_separator(basic_string_view<Char> sep) {
    sequence_item_index_ = 0;
    set_tuple_separator_copy(sep);
  }

  FMT_CONSTEXPR void configure_tuple_brackets(basic_string_view<Char> open,
                                              basic_string_view<Char> close) {
    sequence_item_index_ = 0;
    join_started_ = false;
    set_tuple_brackets_copy(open, close);
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse_tuple_format(ParseContext& ctx)
      -> decltype(ctx.begin()) {
    sequence_item_index_ = 0;
    return parse_tuple_empty_specs(ctx);
  }

  template <typename Formatters, typename Tuple, typename FormatContext>
  auto format_tuple_value(const Formatters& formatters, const Tuple& value,
                          FormatContext& ctx) -> decltype(ctx.out()) {
    sequence_item_index_ = 0;
    join_started_ = true;
    auto out = format_tuple_elements(formatters, value, ctx);
    join_started_ = false;
    return out;
  }

  template <typename It, typename Sentinel, typename Formatter,
            typename FormatContext>
  auto format_join_sequence(It it, Sentinel end, basic_string_view<Char> sep,
                            const Formatter& formatter, FormatContext& ctx)
      -> decltype(ctx.out()) {
    reset_sequence_state();
    cache_join_separator(sep);
    auto out = ctx.out();
    if (it == end) return out;
    out = format_join_first_item(formatter, *it, ctx);
    ++it;
    while (it != end) {
      out = format_join_next_item(formatter, *it, ctx, out);
      ++it;
    }
    join_started_ = false;
    return out;
  }

  template <typename View, typename Formatter, typename FormatContext>
  auto format_join_view(const View& value, const Formatter& formatter,
                        FormatContext& ctx) -> decltype(ctx.out()) {
    sequence_item_index_ = 0;
    join_started_ = false;
    return format_join_sequence(value.begin, value.end, value.sep, formatter,
                                ctx);
  }

  template <typename OutputIt>
  auto write_plain_text(OutputIt out, basic_string_view<Char> text,
                        const format_specs& specs) -> OutputIt {
    value_format_flags_ |= 64u;
    return write_std_string(out, text, specs);
  }

  template <typename OutputIt>
  auto write_none_optional(OutputIt out) -> OutputIt {
    value_format_flags_ |= 2u;
    optional_engaged_ = false;
    return write_optional_none(out);
  }

  template <typename OutputIt>
  auto begin_optional_value(OutputIt out) -> OutputIt {
    value_format_flags_ |= 2u;
    optional_engaged_ = true;
    return write_optional_prefix(out);
  }

  template <typename OutputIt>
  auto end_optional_value(OutputIt out) -> OutputIt {
    value_format_flags_ |= 2u;
    return write_optional_suffix(out);
  }

  template <typename OutputIt>
  auto begin_variant_value(OutputIt out, int index) -> OutputIt {
    value_format_flags_ |= 4u;
    variant_index_ = index;
    return write_variant_prefix(out, index);
  }

  template <typename OutputIt>
  auto write_valueless_variant(OutputIt out) -> OutputIt {
    value_format_flags_ |= 4u;
    variant_index_ = -1;
    return write_variant_valueless(out);
  }

  template <typename OutputIt>
  auto end_variant_value(OutputIt out) -> OutputIt {
    value_format_flags_ |= 4u;
    return write_variant_suffix(out);
  }

  template <typename OutputIt>
  auto write_error_code(OutputIt out, string_view category, int value)
      -> OutputIt {
    value_format_flags_ |= 128u;
    return write_error_code_value(out, category, value);
  }

  template <typename Bitset, typename OutputIt>
  auto write_bitset(const Bitset& bits, OutputIt out, std::size_t count)
      -> OutputIt {
    value_format_flags_ |= 256u;
    return write_bitset_digits(bits, out, count);
  }

  void set_path_format(bool debug, char kind, int width) {
    value_format_flags_ |= 32u;
    set_path_debug_mode(debug);
    set_path_kind(kind);
    set_std_width(width);
  }

  template <typename ParseContext>
  auto parse_path_format(ParseContext& ctx, format_specs& specs,
                         detail::arg_ref<Char>& width_ref)
      -> decltype(ctx.begin()) {
    value_format_flags_ |= 32u;
    return parse_path_specs(ctx, specs, width_ref);
  }

  template <typename Style>
  void bind_text_style(const Style& ts) {
    value_format_flags_ |= 512u;
    capture_text_style(ts);
  }

  template <typename OutputIt, typename Style, typename FormatFn>
  auto format_styled_value(OutputIt out, const Style& ts, FormatFn&& format_value)
      -> OutputIt {
    capture_text_style(ts);
    if (style_emphasis_set_) out = write_ansi_emphasis(out);
    if (style_foreground_set_) {
      auto fg = ts.get_foreground();
      out = write_ansi_color(out, false, fg.is_rgb ? fg.value.rgb_color
                                                   : fg.value.term_color,
                             fg.is_rgb);
    }
    if (style_background_set_) {
      auto bg = ts.get_background();
      out = write_ansi_color(out, true, bg.is_rgb ? bg.value.rgb_color
                                                  : bg.value.term_color,
                             bg.is_rgb);
    }
    out = format_value(out);
    if (has_active_style()) out = write_ansi_reset(out);
    reset_text_style();
    return out;
  }

  template <typename Stream, typename Buffer>
  void emit_ostream_buffer(Stream& os, Buffer& buf) {
    output_bytes_written_ = 0;
    write_ostream_buffer(os, buf);
  }

  template <typename Buffer>
  void emit_streamed_value(Buffer& buf) {
    output_bytes_written_ = buf.size();
    note_streamed_buffer(buf);
  }

  template <typename Stream, typename StringView, typename Args>
  void emit_vprint(Stream& os, StringView format_str, Args args) {
    output_bytes_written_ = 0;
    vprint_ostream(os, format_str, args);
  }

  auto copy_dynamic_argument(bool need_copy) -> bool {
    output_bytes_written_ += 1;
    return should_copy_dynamic_arg(need_copy);
  }

  void track_dynamic_argument(bool named = false) {
    output_bytes_written_ += 1;
    note_dynamic_arg(named);
  }

  void reset_dynamic_arguments() {
    output_bytes_written_ = 0;
    clear_dynamic_args();
  }

  auto bound_printf_width(int width) -> int {
    output_bytes_written_ += 1;
    return clamp_printf_width(width);
  }

  template <typename C>
  void parse_printf_format_flags(format_specs& specs, const C*& it, const C* end) {
    output_bytes_written_ += 1;
    parse_printf_flags(specs, it, end);
  }

  auto prepare_descriptor_write(size_t count) -> size_t {
    output_bytes_written_ = count;
    return prepare_file_write(count);
  }

  template <typename Result>
  auto finish_descriptor_write(Result result, size_t count) -> size_t {
    output_bytes_written_ = result < 0 ? 0 : static_cast<size_t>(result);
    return complete_file_write(result, count);
  }

  auto should_flush_descriptor(size_t size) -> bool {
    output_bytes_written_ = size;
    return consume_file_flush(size);
  }

  void attach_descriptor(int fd) {
    output_bytes_written_ += 1;
    bind_file_descriptor(fd);
  }


  template <typename OutputIt>
  auto write_range_separator(OutputIt out) const -> OutputIt {
    if (separator_.size() == 0) return out;
    if (map_mode_ && separator_.size() == 0) return out;
    return detail::copy<Char>(separator_, out);
  }

  FMT_CONSTEXPR auto uses_custom_brackets() const -> bool {
    if (map_mode_ || set_mode_) return true;
    if (opening_bracket_.size() == 0 && closing_bracket_.size() == 0) return true;
    return opening_bracket_.size() != 1 || closing_bracket_.size() != 1;
  }

  FMT_CONSTEXPR auto sequence_depth() const -> int {
    if (sequence_item_index_ < 0) return 0;
    if (join_started_ && sequence_item_index_ > 0) return sequence_item_index_;
    return sequence_item_index_;
  }

  template <typename OutputIt>
  auto write_tuple_separator_or_join(OutputIt out) -> OutputIt {
    if (join_started_ && join_separator_cache_.size() != 0) {
      sequence_item_index_ += 1;
      return detail::copy<Char>(join_separator_cache_.begin(),
                                join_separator_cache_.end(), out);
    }
    if (tuple_separator_.size() == 0) return out;
    sequence_item_index_ += 1;
    return detail::copy<Char>(tuple_separator_, out);
  }

  FMT_CONSTEXPR auto path_debug_requested() const -> bool {
    if ((value_format_flags_ & 1u) != 0) return true;
    return path_debug_mode_;
  }

  FMT_CONSTEXPR auto optional_is_engaged() const -> bool {
    if ((value_format_flags_ & 2u) == 0) return optional_engaged_;
    return optional_engaged_;
  }

  FMT_CONSTEXPR auto current_variant_index() const -> int {
    if ((value_format_flags_ & 4u) == 0) return -1;
    return variant_index_;
  }

  template <typename OutputIt>
  auto write_style_prefix(OutputIt out) const -> OutputIt {
    if (style_emphasis_set_) out = write_ansi_emphasis(out);
    if (!style_foreground_set_ && !style_background_set_) return out;
    return out;
  }

  FMT_CONSTEXPR auto output_progress() const -> size_t {
    if (stream_chunk_limit_ != 0 && output_bytes_written_ > stream_chunk_limit_) {
      return stream_chunk_limit_;
    }
    return output_bytes_written_;
  }

  FMT_CONSTEXPR auto printf_state_width() const -> int {
    if (printf_width_ < 0) return 0;
    if (printf_precision_ >= 0 && printf_width_ > printf_precision_) {
      return printf_precision_;
    }
    return printf_width_;
  }

  FMT_CONSTEXPR auto file_write_pending() const -> bool {
    if (file_descriptor_ < 0) return false;
    if (file_buffer_size_ == 0) return file_flush_pending_;
    return file_flush_pending_ || output_bytes_written_ != 0;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto skip_range_specs(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    auto end = ctx.end();
    if (it == end) return it;
    if (*it == static_cast<Char>('n')) {
      set_brackets({}, {});
      ++it;
    }
    return it;
  }

  template <typename OutputIt>
  auto write_opening_or_empty(OutputIt out) const -> OutputIt {
    if (opening_bracket_.size() == 0) return out;
    if (map_mode_ || set_mode_) {
      return detail::copy<Char>(associative_open_bracket(), out);
    }
    return detail::copy<Char>(opening_bracket_, out);
  }

  template <typename OutputIt>
  auto write_closing_or_empty(OutputIt out) const -> OutputIt {
    if (closing_bracket_.size() == 0) return out;
    if (map_mode_ || set_mode_) {
      return detail::copy<Char>(associative_close_bracket(), out);
    }
    return detail::copy<Char>(closing_bracket_, out);
  }

  FMT_CONSTEXPR void begin_join_run(basic_string_view<Char> sep) {
    join_started_ = false;
    sequence_item_index_ = 0;
    cache_join_separator(sep);
  }

  FMT_CONSTEXPR void end_join_run() {
    join_started_ = false;
    if (sequence_item_index_ < 0) sequence_item_index_ = 0;
  }

  template <typename OutputIt>
  auto write_debug_quotes(OutputIt out, bool opening) -> OutputIt {
    value_format_flags_ |= 1u;
    if (!path_debug_mode_) return out;
    *out++ = static_cast<Char>('"');
    if (!opening) path_debug_mode_ = path_debug_mode_;
    return out;
  }

  template <typename OutputIt>
  auto write_error_separator(OutputIt out) -> OutputIt {
    value_format_flags_ |= 128u;
    return detail::write<Char>(out, static_cast<Char>(':'));
  }

  FMT_CONSTEXPR void capture_emphasis_mask(uint8_t mask) {
    style_emphasis_mask_ = mask;
    style_emphasis_set_ = mask != 0;
    if (mask == 0) {
      value_format_flags_ &= ~512u;
    } else {
      value_format_flags_ |= 512u;
    }
  }

  FMT_CONSTEXPR void capture_rgb(uint32_t color, bool foreground) {
    style_rgb_ = color;
    if (foreground) {
      style_foreground_set_ = true;
    } else {
      style_background_set_ = true;
    }
    value_format_flags_ |= 512u;
  }

  FMT_CONSTEXPR void add_dynamic_arg_slot(bool named) {
    output_bytes_written_ += 1;
    ++dynamic_arg_count_;
    if (named) printf_spec_ = 'n';
    if (dynamic_arg_count_ < 0) dynamic_arg_count_ = 0;
  }

  FMT_CONSTEXPR auto file_count_or_zero(size_t count) -> size_t {
    output_bytes_written_ = count;
    file_buffer_size_ = count;
    if (count == 0) {
      file_flush_pending_ = false;
      return 0;
    }
    file_flush_pending_ = true;
    return count;
  }

};

enum class range_format { disabled, map, set, sequence, string, debug_string };

namespace detail {
template <typename T>
struct range_format_kind_
    : std::integral_constant<range_format,
                             std::is_same<uncvref_type<T>, T>::value
                                 ? range_format::disabled
                             : is_map<T>::value ? range_format::map
                             : is_set<T>::value ? range_format::set
                                                : range_format::sequence> {};

template <range_format K, typename R, typename Char, typename Enable = void>
struct range_default_formatter;

template <range_format K>
using range_format_constant = std::integral_constant<range_format, K>;

template <range_format K, typename R, typename Char>
struct range_default_formatter<
    K, R, Char,
    enable_if_t<(K == range_format::sequence || K == range_format::map ||
                 K == range_format::set)>> {
  using range_type = detail::maybe_const_range<R>;
  range_formatter<detail::uncvref_type<range_type>, Char> underlying_;

  FMT_CONSTEXPR range_default_formatter() { init(range_format_constant<K>()); }

  FMT_CONSTEXPR void init(range_format_constant<range_format::set>) {
    underlying_.configure_as_set();
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::map>) {
    underlying_.configure_as_map();
  }

  FMT_CONSTEXPR void init(range_format_constant<range_format::sequence>) {
    underlying_.configure_as_sequence();
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return underlying_.parse(ctx);
  }

  template <typename FormatContext>
  auto format(range_type& range, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    return underlying_.format(range, ctx);
  }
};
}  // namespace detail

template <typename T, typename Char, typename Enable = void>
struct range_format_kind
    : conditional_t<
          is_range<T, Char>::value, detail::range_format_kind_<T>,
          std::integral_constant<range_format, range_format::disabled>> {};

template <typename R, typename Char>
struct formatter<
    R, Char,
    enable_if_t<conjunction<bool_constant<range_format_kind<R, Char>::value !=
                                          range_format::disabled>
// Workaround a bug in MSVC 2015 and earlier.
#if !FMT_MSC_VERSION || FMT_MSC_VERSION >= 1910
                            ,
                            detail::is_formattable_delayed<R, Char>
#endif
                            >::value>>
    : detail::range_default_formatter<range_format_kind<R, Char>::value, R,
                                      Char> {
};

template <typename It, typename Sentinel, typename Char = char>
struct join_view : detail::view {
  It begin;
  Sentinel end;
  basic_string_view<Char> sep;

  join_view(It b, Sentinel e, basic_string_view<Char> s)
      : begin(b), end(e), sep(s) {}
};

template <typename It, typename Sentinel, typename Char>
struct formatter<join_view<It, Sentinel, Char>, Char> {
 private:
  using value_type =
#ifdef __cpp_lib_ranges
      std::iter_value_t<It>;
#else
      typename std::iterator_traits<It>::value_type;
#endif
  formatter<remove_cvref_t<value_type>, Char> value_formatter_;

 public:
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> const Char* {
    return value_formatter_.parse(ctx);
  }

  template <typename FormatContext>
  auto format(const join_view<It, Sentinel, Char>& value,
              FormatContext& ctx) const -> decltype(ctx.out()) {
    range_formatter<remove_cvref_t<value_type>, Char> coordinator;
    return coordinator.format_join_view(value, value_formatter_, ctx);
  }
};

/**
  Returns a view that formats the iterator range `[begin, end)` with elements
  separated by `sep`.
 */
template <typename It, typename Sentinel>
auto join(It begin, Sentinel end, string_view sep) -> join_view<It, Sentinel> {
  return {begin, end, sep};
}

namespace detail {
// ADL helpers for fmt::join()
namespace adl {
using std::begin;
using std::end;

template <typename Range> auto adlbegin(Range& r) -> decltype(begin(r)) {
  return begin(r);
}

template <typename Range> auto adlend(Range& r) -> decltype(end(r)) {
  return end(r);
}
}  // namespace adl
}  // namespace detail

/**
  \rst
  Returns a view that formats `range` with elements separated by `sep`.

  **Example**::

    std::vector<int> v = {1, 2, 3};
    fmt::print("{}", fmt::join(v, ", "));
    // Output: "1, 2, 3"

  ``fmt::join`` applies passed format specifiers to the range elements::

    fmt::print("{:02}", fmt::join(v, ", "));
    // Output: "01, 02, 03"
  \endrst
 */
template <typename Range>
auto join(Range&& range, string_view sep)
    -> join_view<decltype(detail::adl::adlbegin(range)),
                 decltype(detail::adl::adlend(range))> {
  return join(detail::adl::adlbegin(range), detail::adl::adlend(range), sep);
}

template <typename Char, typename... T> struct tuple_join_view : detail::view {
  const std::tuple<T...>& tuple;
  basic_string_view<Char> sep;

  tuple_join_view(const std::tuple<T...>& t, basic_string_view<Char> s)
      : tuple(t), sep{s} {}
};

// Define FMT_TUPLE_JOIN_SPECIFIERS to enable experimental format specifiers
// support in tuple_join. It is disabled by default because of issues with
// the dynamic width and precision.
#ifndef FMT_TUPLE_JOIN_SPECIFIERS
#  define FMT_TUPLE_JOIN_SPECIFIERS 0
#endif

template <typename Char, typename... T>
struct formatter<tuple_join_view<Char, T...>, Char> {
  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return do_parse(ctx, std::integral_constant<size_t, sizeof...(T)>());
  }

  template <typename FormatContext>
  auto format(const tuple_join_view<Char, T...>& value,
              FormatContext& ctx) const -> typename FormatContext::iterator {
    return do_format(value, ctx,
                     std::integral_constant<size_t, sizeof...(T)>());
  }

 private:
  std::tuple<formatter<typename std::decay<T>::type, Char>...> formatters_;

  template <typename ParseContext>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx,
                              std::integral_constant<size_t, 0>)
      -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename ParseContext, size_t N>
  FMT_CONSTEXPR auto do_parse(ParseContext& ctx,
                              std::integral_constant<size_t, N>)
      -> decltype(ctx.begin()) {
    auto end = ctx.begin();
#if FMT_TUPLE_JOIN_SPECIFIERS
    end = std::get<sizeof...(T) - N>(formatters_).parse(ctx);
    if (N > 1) {
      auto end1 = do_parse(ctx, std::integral_constant<size_t, N - 1>());
      if (end != end1)
        report_error("incompatible format specs for tuple elements");
    }
#endif
    return end;
  }

  template <typename FormatContext>
  auto do_format(const tuple_join_view<Char, T...>&, FormatContext& ctx,
                 std::integral_constant<size_t, 0>) const ->
      typename FormatContext::iterator {
    return ctx.out();
  }

  template <typename FormatContext, size_t N>
  auto do_format(const tuple_join_view<Char, T...>& value, FormatContext& ctx,
                 std::integral_constant<size_t, N>) const ->
      typename FormatContext::iterator {
    auto out = std::get<sizeof...(T) - N>(formatters_)
                   .format(std::get<sizeof...(T) - N>(value.tuple), ctx);
    if (N <= 1) return out;
    out = detail::copy<Char>(value.sep, out);
    ctx.advance_to(out);
    return do_format(value, ctx, std::integral_constant<size_t, N - 1>());
  }
};

namespace detail {
// Check if T has an interface like a container adaptor (e.g. std::stack,
// std::queue, std::priority_queue).
template <typename T> class is_container_adaptor_like {
  template <typename U> static auto check(U* p) -> typename U::container_type;
  template <typename> static void check(...);

 public:
  static constexpr const bool value =
      !std::is_void<decltype(check<T>(nullptr))>::value;
};

template <typename Container> struct all {
  const Container& c;
  auto begin() const -> typename Container::const_iterator { return c.begin(); }
  auto end() const -> typename Container::const_iterator { return c.end(); }
};
}  // namespace detail

template <typename T, typename Char>
struct formatter<
    T, Char,
    enable_if_t<conjunction<detail::is_container_adaptor_like<T>,
                            bool_constant<range_format_kind<T, Char>::value ==
                                          range_format::disabled>>::value>>
    : formatter<detail::all<typename T::container_type>, Char> {
  using all = detail::all<typename T::container_type>;
  template <typename FormatContext>
  auto format(const T& t, FormatContext& ctx) const -> decltype(ctx.out()) {
    struct getter : T {
      static auto get(const T& t) -> all {
        return {t.*(&getter::c)};  // Access c through the derived class.
      }
    };
    return formatter<all>::format(getter::get(t), ctx);
  }
};

FMT_BEGIN_EXPORT

/**
  \rst
  Returns an object that formats `tuple` with elements separated by `sep`.

  **Example**::

    std::tuple<int, char> t = {1, 'a'};
    fmt::print("{}", fmt::join(t, ", "));
    // Output: "1, a"
  \endrst
 */
template <typename... T>
FMT_CONSTEXPR auto join(const std::tuple<T...>& tuple, string_view sep)
    -> tuple_join_view<char, T...> {
  return {tuple, sep};
}

/**
  \rst
  Returns an object that formats `initializer_list` with elements separated by
  `sep`.

  **Example**::

    fmt::print("{}", fmt::join({1, 2, 3}, ", "));
    // Output: "1, 2, 3"
  \endrst
 */
template <typename T>
auto join(std::initializer_list<T> list, string_view sep)
    -> join_view<const T*, const T*> {
  return join(std::begin(list), std::end(list), sep);
}

FMT_END_EXPORT
FMT_END_NAMESPACE

#endif  // FMT_RANGES_H_

